    if (this.dragging?.enabled()) {
      this.options.draggable = true;
      this.dragging.removeHooks();
    }
    delete this.dragging;
    if (this._zoomAnimated) {
      map.off('zoomanim', this._animateZoom, this);
    }
    this._removeIcon();
    this._removeShadow();
  }
  getEvents() {
    return {
      zoom: this.update,
      viewreset: this.update
    };
  }

  // @method getLatLng: LatLng
  // Returns the current geographical position of the marker.
  getLatLng() {
    return this._latlng;
  }

  // @method setLatLng(latlng: LatLng): this
  // Changes the marker position to the given point.
  setLatLng(latlng) {
    const oldLatLng = this._latlng;
    this._latlng = new LatLng(latlng);
    this.update();

    // @event move: Event
    // Fired when the marker is moved via [`setLatLng`](#marker-setlatlng) or by [dragging](#marker-dragging). Old and new coordinates are included in event arguments as `oldLatLng`, `latlng`.
    return this.fire('move', {
      oldLatLng,
      latlng: this._latlng
    });
  }

  // @method setZIndexOffset(offset: Number): this
  // Changes the [zIndex offset](#marker-zindexoffset) of the marker.
  setZIndexOffset(offset) {
    this.options.zIndexOffset = offset;
    return this.update();
  }

  // @method getIcon: Icon
  // Returns the current icon used by the marker
  getIcon() {
    return this.options.icon;
  }

  // @method setIcon(icon: Icon): this
  // Changes the marker icon.
  setIcon(icon) {
    this.options.icon = icon;
    if (this._map) {
      this._initIcon();
      this.update();
    }
    if (this._popup) {
      this.bindPopup(this._popup, this._popup.options);
    }
    return this;
  }

  // @method getElement(): HTMLElement
  // Returns the instance of [`HTMLElement`](https://developer.mozilla.org/docs/Web/API/HTMLElement)
  // used by Marker layer.
  getElement() {
    return this._icon;
  }
  update() {
    if (this._icon && this._map) {
      const pos = this._map.latLngToLayerPoint(this._latlng).round();
      this._setPos(pos);
    }
    return this;
  }
  _initIcon() {
    const options = this.options,
      classToAdd = `leaflet-zoom-${this._zoomAnimated ? 'animated' : 'hide'}`;
    const icon = options.icon.createIcon(this._icon);
    let addIcon = false;

    // if we're not reusing the icon, remove the old one and init new one
    if (icon !== this._icon) {
      if (this._icon) {
        this._removeIcon();
      }
      addIcon = true;
      if (options.title) {
        icon.title = options.title;
      }
      if (icon.tagName === 'IMG') {
        icon.alt = options.alt ?? '';
      }
    }
    icon.classList.add(classToAdd);
    if (options.keyboard) {
      icon.tabIndex = '0';
      icon.setAttribute('role', 'button');
    }
    this._icon = icon;
    if (options.riseOnHover) {
      this.on({
        pointerover: this._bringToFront,
        pointerout: this._resetZIndex
      });
    }
    if (this.options.autoPanOnFocus) {
      on(icon, 'focus', this._panOnFocus, this);
    }
    const newShadow = options.icon.createShadow(this._shadow);
    let addShadow = false;
    if (newShadow !== this._shadow) {
      this._removeShadow();
      addShadow = true;
    }
    if (newShadow) {
      newShadow.classList.add(classToAdd);
      newShadow.alt = '';
    }
    this._shadow = newShadow;
    if (options.opacity < 1) {
      this._updateOpacity();
    }
    if (addIcon) {
      this.getPane().appendChild(this._icon);
    }
    this._initInteraction();
    if (newShadow && addShadow) {
      this.getPane(options.shadowPane).appendChild(this._shadow);
    }
  }
  _removeIcon() {
    if (this.options.riseOnHover) {
      this.off({
        pointerover: this._bringToFront,
        pointerout: this._resetZIndex
      });
    }
    if (this.options.autoPanOnFocus) {
      off(this._icon, 'focus', this._panOnFocus, this);
    }
    this._icon.remove();
    this.removeInteractiveTarget(this._icon);
    this._icon = null;
  }
  _removeShadow() {
    this._shadow?.remove();
    this._shadow = null;
  }
  _setPos(pos) {
    if (this._icon) {
      setPosition(this._icon, pos);
    }
    if (this._shadow) {
      setPosition(this._shadow, pos);
    }
    this._zIndex = pos.y + this.options.zIndexOffset;
    this._resetZIndex();
  }
  _updateZIndex(offset) {
    if (this._icon) {
      this._icon.style.zIndex = this._zIndex + offset;
    }
  }
  _animateZoom(opt) {
    const pos = this._map._latLngToNewLayerPoint(this._latlng, opt.zoom, opt.center).round();
    this._setPos(pos);
  }
  _initInteraction() {
    if (!this.options.interactive) {
      return;
    }
    this._icon.classList.add('leaflet-interactive');
    this.addInteractiveTarget(this._icon);
    if (MarkerDrag) {
      let draggable = this.options.draggable;
      if (this.dragging) {
        draggable = this.dragging.enabled();
        this.dragging.disable();
      }
      this.dragging = new MarkerDrag(this);
      if (draggable) {
        this.dragging.enable();
      }
    }
  }

  // @method setOpacity(opacity: Number): this
  // Changes the opacity of the marker.
  setOpacity(opacity) {
    this.options.opacity = opacity;
    if (this._map) {
      this._updateOpacity();
    }
    return this;
  }
  _updateOpacity() {
    const opacity = this.options.opacity;
    if (this._icon) {
      this._icon.style.opacity = opacity;
    }
    if (this._shadow) {
      this._shadow.style.opacity = opacity;
    }
  }
  _bringToFront() {
    this._updateZIndex(this.options.riseOffset);
  }
  _resetZIndex() {
    this._updateZIndex(0);
  }
  _panOnFocus() {
    const map = this._map;
    if (!map) {
      return;
    }
    const iconOpts = this.options.icon.options;
    const size = iconOpts.iconSize ? new Point(iconOpts.iconSize) : new Point(0, 0);
    const anchor = iconOpts.iconAnchor ? new Point(iconOpts.iconAnchor) : new Point(0, 0);
    map.panInside(this._latlng, {
      paddingTopLeft: anchor,
      paddingBottomRight: size.subtract(anchor)
    });
  }
  _getPopupAnchor() {
    return this.options.icon.options.popupAnchor;
  }
  _getTooltipAnchor() {
    return this.options.icon.options.tooltipAnchor;
  }
}

/*
 * @class Path
 * @inherits Interactive layer
 *
 * An abstract class that contains options and constants shared between vector
 * overlays (Polygon, Polyline, Circle). Do not use it directly. Extends `Layer`.
 */

class Path extends Layer {
  static {
    // @section
    // @aka Path options
    this.setDefaultOptions({
      // @option stroke: Boolean = true
      // Whether to draw stroke along the path. Set it to `false` to disable borders on polygons or circles.
      stroke: true,
      // @option color: String = '#3388ff'
      // Stroke color
      color: '#3388ff',
      // @option weight: Number = 3
      // Stroke width in pixels
      weight: 3,
      // @option opacity: Number = 1.0
      // Stroke opacity
      opacity: 1,
      // @option lineCap: String= 'round'
      // A string that defines [shape to be used at the end](https://developer.mozilla.org/docs/Web/SVG/Attribute/stroke-linecap) of the stroke.
      lineCap: 'round',
      // @option lineJoin: String = 'round'
      // A string that defines [shape to be used at the corners](https://developer.mozilla.org/docs/Web/SVG/Attribute/stroke-linejoin) of the stroke.
      lineJoin: 'round',
      // @option dashArray: String = null
      // A string that defines the stroke [dash pattern](https://developer.mozilla.org/docs/Web/SVG/Attribute/stroke-dasharray).
      dashArray: null,
      // @option dashOffset: String = null
      // A string that defines the [distance into the dash pattern to start the dash](https://developer.mozilla.org/docs/Web/SVG/Attribute/stroke-dashoffset).
      dashOffset: null,
      // @option fill: Boolean = depends
      // Whether to fill the path with color. Set it to `false` to disable filling on polygons or circles.
      fill: false,
      // @option fillColor: String = *
      // Fill color. Defaults to the value of the [`color`](#path-color) option
      fillColor: null,
      // @option fillOpacity: Number = 0.2
      // Fill opacity.
      fillOpacity: 0.2,
      // @option fillRule: String = 'evenodd'
      // A string that defines [how the inside of a shape](https://developer.mozilla.org/docs/Web/SVG/Attribute/fill-rule) is determined.
      fillRule: 'evenodd',
      // className: '',

      // Option inherited from "Interactive layer" abstract class
      interactive: true,
      // @option bubblingPointerEvents: Boolean = true
      // When `true`, a pointer event on this path will trigger the same event on the map
      // (unless [`DomEvent.stopPropagation`](#domevent-stoppropagation) is used).
      bubblingPointerEvents: true
    });
  }
  beforeAdd(map) {
    // Renderer is set here because we need to call renderer.getEvents
    // before this.getEvents.
    this._renderer = map.getRenderer(this);
  }
  onAdd() {
    this._renderer._initPath(this);
    this._reset();
    this._renderer._addPath(this);
  }
  onRemove() {
    this._renderer._removePath(this);
  }

  // @method redraw(): this
  // Redraws the layer. Sometimes useful after you changed the coordinates that the path uses.
  redraw() {
    if (this._map) {
      this._renderer._updatePath(this);
    }
    return this;
  }

  // @method setStyle(style: Path options): this
  // Changes the appearance of a Path based on the options in the `Path options` object.
  setStyle(style) {
    setOptions(this, style);
    if (this._renderer) {
      this._renderer._updateStyle(this);
      if (this.options.stroke && style && Object.hasOwn(style, 'weight')) {
        this._updateBounds();
      }
    }
    return this;
  }

  // @method bringToFront(): this
  // Brings the layer to the top of all path layers.
  bringToFront() {
    this._renderer?._bringToFront(this);
    return this;
  }

  // @method bringToBack(): this
  // Brings the layer to the bottom of all path layers.
  bringToBack() {
    this._renderer?._bringToBack(this);
    return this;
  }
  getElement() {
    return this._path;
  }
  _reset() {
    // defined in child classes
    this._project();
    this._update();
  }
  _clickTolerance() {
    // used when doing hit detection for Canvas layers
    return (this.options.stroke ? this.options.weight / 2 : 0) + (this._renderer.options.tolerance || 0);
  }
}

/*
 * @class CircleMarker
 * @inherits Path
 *
 * A circle of a fixed size with radius specified in pixels. Extends `Path`.
 */

// @constructor CircleMarker(latlng: LatLng, options?: CircleMarker options)
// Instantiates a circle marker object given a geographical point, and an optional options object.
class CircleMarker extends Path {
  static {
    // @section
    // @aka CircleMarker options
    this.setDefaultOptions({
      fill: true,
      // @option radius: Number = 10
      // Radius of the circle marker, in pixels
      radius: 10
    });
  }
  initialize(latlng, options) {
    setOptions(this, options);
    this._latlng = new LatLng(latlng);
    this._radius = this.options.radius;
  }

  // @method setLatLng(latLng: LatLng): this
  // Sets the position of a circle marker to a new location.
  setLatLng(latlng) {
    const oldLatLng = this._latlng;
    this._latlng = new LatLng(latlng);
    this.redraw();

    // @event move: Event
    // Fired when the marker is moved via [`setLatLng`](#circlemarker-setlatlng). Old and new coordinates are included in event arguments as `oldLatLng`, `latlng`.
    return this.fire('move', {
      oldLatLng,
      latlng: this._latlng
    });
  }

  // @method getLatLng(): LatLng
  // Returns the current geographical position of the circle marker
  getLatLng() {
    return this._latlng;
  }

  // @method setRadius(radius: Number): this
  // Sets the radius of a circle marker. Units are in pixels.
  setRadius(radius) {
    this.options.radius = this._radius = radius;
    return this.redraw();
  }

  // @method getRadius(): Number
  // Returns the current radius of the circle
  getRadius() {
    return this._radius;
  }
  setStyle(options) {
    const radius = options?.radius ?? this._radius;
    Path.prototype.setStyle.call(this, options);
    this.setRadius(radius);
    return this;
  }
  _project() {
    this._point = this._map.latLngToLayerPoint(this._latlng);
    this._updateBounds();
  }
  _updateBounds() {
    const r = this._radius,
      r2 = this._radiusY ?? r,
      w = this._clickTolerance(),
      p = [r + w, r2 + w];
    this._pxBounds = new Bounds(this._point.subtract(p), this._point.add(p));
  }
  _update() {
    if (this._map) {
      this._updatePath();
    }
  }
  _updatePath() {
    this._renderer._updateCircle(this);
  }
  _empty() {
    return this._radius && !this._renderer._bounds.intersects(this._pxBounds);
  }

  // Needed by the `Canvas` renderer for interactivity
  _containsPoint(p) {
    return p.distanceTo(this._point) <= this._radius + this._clickTolerance();
  }
}

/*
 * @class Circle
 * @inherits CircleMarker
 *
 * A class for drawing circle overlays on a map. Extends `CircleMarker`.
 *
 * It's an approximation and starts to diverge from a real circle closer to poles (due to projection distortion).
 *
 * @example
 *
 * ```js
 * new Circle([50.5, 30.5], {radius: 200}).addTo(map);
 * ```
 */

// @constructor Circle(latlng: LatLng, options?: Circle options)
// Instantiates a circle object given a geographical point, and an options object
// which contains the circle radius.
class Circle extends CircleMarker {
  initialize(latlng, options) {
    setOptions(this, options);
    this._latlng = new LatLng(latlng);
    if (isNaN(this.options.radius)) {
      throw new Error('Circle radius cannot be NaN');
    }

    // @section
    // @aka Circle options
    // @option radius: Number; Radius of the circle, in meters.
    this._mRadius = this.options.radius;
  }

  // @method setRadius(radius: Number): this
  // Sets the radius of a circle. Units are in meters.
  setRadius(radius) {
    this._mRadius = radius;
    return this.redraw();
  }

  // @method getRadius(): Number
  // Returns the current radius of a circle. Units are in meters.
  getRadius() {
    return this._mRadius;
  }

  // @method getBounds(): LatLngBounds
  // Returns the `LatLngBounds` of the path.
  getBounds() {
    const half = [this._radius, this._radiusY ?? this._radius];
    return new LatLngBounds(this._map.layerPointToLatLng(this._point.subtract(half)), this._map.layerPointToLatLng(this._point.add(half)));
  }
  setStyle = Path.prototype.setStyle;
  _project() {
    const lng = this._latlng.lng,
      lat = this._latlng.lat,
      map = this._map,
      crs = map.options.crs;
    if (crs.distance === Earth.distance) {
      const d = Math.PI / 180,
        latR = this._mRadius / Earth.R / d,
        top = map.project([lat + latR, lng]),
        bottom = map.project([lat - latR, lng]),
        p = top.add(bottom).divideBy(2),
        lat2 = map.unproject(p).lat;
      let lngR = Math.acos((Math.cos(latR * d) - Math.sin(lat * d) * Math.sin(lat2 * d)) / (Math.cos(lat * d) * Math.cos(lat2 * d))) / d;
      if (isNaN(lngR) || lngR === 0) {
        lngR = latR / Math.cos(Math.PI / 180 * lat); // Fallback for edge case, #2425
      }
      this._point = p.subtract(map.getPixelOrigin());
      this._radius = isNaN(lngR) ? 0 : p.x - map.project([lat2, lng - lngR]).x;
      this._radiusY = p.y - top.y;
    } else {
      const latlng2 = crs.unproject(crs.project(this._latlng).subtract([this._mRadius, 0]));
      this._point = map.latLngToLayerPoint(this._latlng);
      this._radius = Math.abs(this._point.x - map.latLngToLayerPoint(latlng2).x);
    }
    this._updateBounds();
  }
}

/*
 * @class Polyline
 * @inherits Path
 *
 * A class for drawing polyline overlays on a map. Extends `Path`.
 *
 * @example
 *
 * ```js
 * // create a red polyline from an array of LatLng points
 * const latlngs = [
 * 	[45.51, -122.68],
 * 	[37.77, -122.43],
 * 	[34.04, -118.2]
 * ];
 *
 * const polyline = new Polyline(latlngs, {color: 'red'}).addTo(map);
 *
 * // zoom the map to the polyline
 * map.fitBounds(polyline.getBounds());
 * ```
 *
 * You can also pass a multi-dimensional array to represent a `MultiPolyline` shape:
 *
 * ```js
 * // create a red polyline from an array of arrays of LatLng points
 * const latlngs = [
 * 	[[45.51, -122.68],
 * 	 [37.77, -122.43],
 * 	 [34.04, -118.2]],
 * 	[[40.78, -73.91],
 * 	 [41.83, -87.62],
 * 	 [32.76, -96.72]]
 * ];
 * ```
 */

// @constructor Polyline(latlngs: LatLng[], options?: Polyline options)
// Instantiates a polyline object given an array of geographical points and
// optionally an options object. You can create a `Polyline` object with
// multiple separate lines (`MultiPolyline`) by passing an array of arrays
// of geographic points.
class Polyline extends Path {
  static {
    // @section
    // @aka Polyline options
    this.setDefaultOptions({
      // @option smoothFactor: Number = 1.0
      // How much to simplify the polyline on each zoom level. More means
      // better performance and smoother look, and less means more accurate representation.
      smoothFactor: 1.0,
      // @option noClip: Boolean = false
      // Disable polyline clipping.
      noClip: false
    });
  }
  initialize(latlngs, options) {
    setOptions(this, options);
    this._setLatLngs(latlngs);
  }

  // @method getLatLngs(): LatLng[]
  // Returns an array of the points in the path, or nested arrays of points in case of multi-polyline.
  getLatLngs() {
    return this._latlngs;
  }

  // @method setLatLngs(latlngs: LatLng[]): this
  // Replaces all the points in the polyline with the given array of geographical points.
  setLatLngs(latlngs) {
    this._setLatLngs(latlngs);
    return this.redraw();
  }

  // @method isEmpty(): Boolean
  // Returns `true` if the Polyline has no LatLngs.
  isEmpty() {
    return !this._latlngs.length;
  }

  // @method closestLayerPoint(p: Point): Point
  // Returns the point closest to `p` on the Polyline.
  closestLayerPoint(p) {
    p = new Point(p);
    let minDistance = Infinity,
      minPoint = null,
      p1,
      p2;
    const closest = _sqClosestPointOnSegment;
    for (const points of this._parts) {
      for (let i = 1, len = points.length; i < len; i++) {
        p1 = points[i - 1];
        p2 = points[i];
        const sqDist = closest(p, p1, p2, true);
        if (sqDist < minDistance) {
          minDistance = sqDist;
          minPoint = closest(p, p1, p2);
        }
      }
    }
    if (minPoint) {
      minPoint.distance = Math.sqrt(minDistance);
    }
    return minPoint;
  }

  // @method getCenter(): LatLng
  // Returns the center ([centroid](https://en.wikipedia.org/wiki/Centroid)) of the polyline.
  getCenter() {
    // throws error when not yet added to map as this center calculation requires projected coordinates
    if (!this._map) {
      throw new Error('Must add layer to map before using getCenter()');
    }
    return polylineCenter(this._defaultShape(), this._map.options.crs);
  }

  // @method getBounds(): LatLngBounds
  // Returns the `LatLngBounds` of the path.
  getBounds() {
    return this._bounds;
  }

  // @method addLatLng(latlng: LatLng, latlngs?: LatLng[]): this
  // Adds a given point to the polyline. By default, adds to the first ring of
  // the polyline in case of a multi-polyline, but can be overridden by passing
  // a specific ring as a LatLng array (that you can earlier access with [`getLatLngs`](#polyline-getlatlngs)).
  addLatLng(latlng, latlngs) {
    latlngs ??= this._defaultShape();
    latlng = new LatLng(latlng);
    latlngs.push(latlng);
    this._bounds.extend(latlng);
    return this.redraw();
  }
  _setLatLngs(latlngs) {
    this._bounds = new LatLngBounds();
    this._latlngs = this._convertLatLngs(latlngs);
  }
  _defaultShape() {
    return isFlat(this._latlngs) ? this._latlngs : this._latlngs[0];
  }

  // recursively convert latlngs input into actual LatLng instances; calculate bounds along the way
  _convertLatLngs(latlngs) {
    const result = [],
      flat = isFlat(latlngs);
    for (let i = 0, len = latlngs.length; i < len; i++) {
      if (flat) {
        result[i] = new LatLng(latlngs[i]);
        this._bounds.extend(result[i]);
      } else {
        result[i] = this._convertLatLngs(latlngs[i]);
      }
    }
    return result;
  }
  _project() {
    const pxBounds = new Bounds();
    this._rings = [];
    this._projectLatlngs(this._latlngs, this._rings, pxBounds);
    if (this._bounds.isValid() && pxBounds.isValid()) {
      this._rawPxBounds = pxBounds;
      this._updateBounds();
    }
  }
  _updateBounds() {
    const w = this._clickTolerance(),
      p = new Point(w, w);
    if (!this._rawPxBounds) {
      return;
    }
    this._pxBounds = new Bounds([this._rawPxBounds.min.subtract(p), this._rawPxBounds.max.add(p)]);
  }

  // recursively turns latlngs into a set of rings with projected coordinates
  _projectLatlngs(latlngs, result, projectedBounds) {
    const flat = latlngs[0] instanceof LatLng;
    if (flat) {
      const ring = latlngs.map(latlng => this._map.latLngToLayerPoint(latlng));
      ring.forEach(r => projectedBounds.extend(r));
      result.push(ring);
    } else {
      latlngs.forEach(latlng => this._projectLatlngs(latlng, result, projectedBounds));
    }
  }

  // clip polyline by renderer bounds so that we have less to render for performance
  _clipPoints() {
    const bounds = this._renderer._bounds;
    this._parts = [];
    if (!this._pxBounds || !this._pxBounds.intersects(bounds)) {
      return;
    }
    if (this.options.noClip) {
      this._parts = this._rings;
      return;
    }
    const parts = this._parts;
    let i, j, k, len, len2, segment, points;
    for (i = 0, k = 0, len = this._rings.length; i < len; i++) {
      points = this._rings[i];
      for (j = 0, len2 = points.length; j < len2 - 1; j++) {
        segment = clipSegment(points[j], points[j + 1], bounds, j, true);
        if (!segment) {
          continue;
        }
        parts[k] ??= [];
        parts[k].push(segment[0]);

        // if segment goes out of screen, or it's the last one, it's the end of the line part
        if (segment[1] !== points[j + 1] || j === len2 - 2) {
          parts[k].push(segment[1]);
          k++;
        }
      }
    }
  }

  // simplify each clipped part of the polyline for performance
  _simplifyPoints() {
    const parts = this._parts,
      tolerance = this.options.smoothFactor;
    for (let i = 0, len = parts.length; i < len; i++) {
      parts[i] = simplify(parts[i], tolerance);
    }
  }
  _update() {
    if (!this._map) {
      return;
    }
    this._clipPoints();
    this._simplifyPoints();
    this._updatePath();
