    }
  }
  _initPath(layer) {
    this._updateDashArray(layer);
    this._layers[stamp(layer)] = layer;
    const order = layer._order = {
      layer,
      prev: this._drawLast,
      next: null
    };
    if (this._drawLast) {
      this._drawLast.next = order;
    }
    this._drawLast = order;
    this._drawFirst ??= this._drawLast;
  }
  _addPath(layer) {
    this._requestRedraw(layer);
  }
  _removePath(layer) {
    const order = layer._order;
